using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Web.Script.Serialization;

internal static class PlayerVitalVerification {
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static void Var(List<byte> b,uint value){do{byte n=(byte)(value&127);value>>=7;b.Add((byte)(n|(value>0?128:0)));}while(value>0);}
    static byte[] Delta(uint actor,uint? hp=null,uint? maximum=null,uint? mp=null){var b=new List<byte>{0,0x8d};Var(b,actor);b.Add((byte)((mp.HasValue?1:0)|(hp.HasValue||maximum.HasValue?2:0)));if(mp.HasValue){Var(b,1);b.Add(1);b.AddRange(BitConverter.GetBytes(mp.Value));}if(hp.HasValue||maximum.HasValue){Var(b,(uint)((hp.HasValue?1:0)+(maximum.HasValue?1:0)));if(hp.HasValue){b.Add(0);b.AddRange(BitConverter.GetBytes((long)hp.Value));}if(maximum.HasValue){b.Add(7);b.AddRange(BitConverter.GetBytes((long)maximum.Value));}}return b.ToArray();}
    static void Feed(PlayerVitalSignal s,byte[] b,double t,string flow="A"){s.Consume(b,0,b.Length,t,flow);}
    static void VerifySignal(){
        var s=new PlayerVitalSignal();double t=DpsHistory.UtcNow();var profile=EnemyTargetVerification.Player(13351,"Charlotta",12683,12683,true);
        Feed(s,profile,t);Check(s.Read(false,t)==null,"Disabled vital reader ignores frames");s.Configure(true);Feed(s,Delta(13351,10195,null,4304),t);Check(s.Read(false,t)==null&&s.Read(true,t)==null,"Deltas cannot invent identity or maximum");
        Feed(s,profile,t);Check(s.Read(false,t).Maximum==12683&&s.Read(true,t).Maximum==4591,"Own profile supplies explicit HP and MP maxima");
        Feed(s,Delta(13351,10195,null,4304),t+1);Check(s.Read(false,t+1).Current==10195&&s.Read(true,t+1).Current==4304,"Own poison and MP updates");Feed(s,Delta(13351,10123),t+2);Check(s.Read(false,t+2).Current==10123,"Consecutive poison values are absolute HP, not damage estimates");
        Feed(s,EnemyTargetVerification.Player(888,"Other",500,1000,false),t+2);Feed(s,Delta(888,1,null,1),t+2);Feed(s,Delta(13351,2,null,2),t+2,"B");Check(s.Read(false,t+2).Current==10123&&s.Read(true,t+2).Current==4304,"Other actors and flows cannot replace own resources");
        Feed(s,Delta(13351,12683,12683,4591),t+3);Feed(s,Delta(13351,12387,12387),t+4);Check(s.Read(false,t+4).Maximum==12387,"Unequipping replaces maximum rather than retaining highest seen");Feed(s,Delta(13351,12683,12683,4591),t+5);Check(s.Read(false,t+5).Maximum==12683,"Reequipping restores explicit maximum");Feed(s,Delta(13351,1,null,1),t+4);Check(s.Read(false,t+5).Current==12683,"Old updates cannot overwrite newer resource state");
        var broken=Delta(13351,100,null,4000);for(int length=0;length<broken.Length;length++)s.Consume(broken,0,length,t+5,"A");Check(s.Read(false,t+5).Current==12683&&s.Read(true,t+5).Current==4591,"Truncated mixed resources cannot partially apply");
        Feed(s,Delta(13351,0,null,0),t+6);Check(s.Read(false,t+6).Current==0&&s.Read(true,t+6).Current==0,"Actual death and exhausted MP remain valid zeros");Check(s.Read(false,t+12)==null,"Silent connection expires static resources");
        Feed(s,Delta(13351,1,null,1),t+40);Check(s.Read(false,t+40)==null,"Long traffic gap clears inherited maxima");Feed(s,profile,t+41);
        var map=new byte[48];map[0]=0x21;map[1]=0x36;Array.Copy(BitConverter.GetBytes(123u),0,map,6,4);Feed(s,map,t+41);Check(s.Read(false,t+41)!=null,"Own profile just before map frame is retained");Array.Copy(BitConverter.GetBytes(124u),0,map,6,4);Feed(s,map,t+45);Check(s.Read(false,t+45)==null,"New zone clears previous character resources");Feed(s,profile,t+46);Check(s.Read(true,t+46)!=null,"New own profile resumes tracking");s.Reset();Check(s.Read(false,t+46)==null,"Transport reset clears own resources");
        var random=new Random(617);for(int i=0;i<3000;i++){var bytes=new byte[random.Next(2,400)];random.NextBytes(bytes);int[] ops={0x3336,0x008d,0x1b92,0x2136};int op=ops[i%ops.Length];bytes[0]=(byte)(op>>8);bytes[1]=(byte)op;Feed(s,bytes,t+50+i*.0001);}
    }
    static Rectangle TextArea(PlayerVitalDesign.Caption caption){var area=caption.Bounds;int pad=(caption.Options.Outline.Enabled?Math.Min(8,caption.Outline):0)+2;area.Inflate(pad,pad);return area;}
    static void VerifyNarrow(string root){foreach(bool mana in new[]{false,true})foreach(int width in new[]{80,120,180,230,280,420})foreach(int scale in new[]{50,100,175,300})foreach(int value in new[]{0,80,100}){
        var o=PlayerVitalOptions.Defaults(mana);o.Bounds=new Rectangle(0,0,width,12);o.Bar.ScalePercent=scale;var before=o.Copy();var layout=PlayerVitalDesign.Measure(o,mana,value/100.0);for(int i=0;i<layout.Captions.Count;i++)for(int j=i+1;j<layout.Captions.Count;j++)Check(!TextArea(layout.Captions[i]).IntersectsWith(TextArea(layout.Captions[j])),"Narrow HP/MP labels and outlines must never overlap");Check(PlayerVitalOptions.Same(o,before),"Automatic fitting cannot overwrite chosen text settings");
        if(width==420&&scale==100)foreach(var caption in layout.Captions)Check(caption.Bounds.Bottom==layout.Captions[0].Bounds.Bottom,"Wide default layout retains the approved single text row at monitor DPI");
        if(scale==100&&value==80)using(var image=PlayerVitalDesign.Render(o,mana,.8,false))image.Bitmap.Save(Path.Combine(root,"designs","player-narrow-"+(mana?"mp":"hp")+"-"+width+".png"));
    }}
    internal static void Run(string root){
        var inspected=PlayerVitalDesign.Measure(PlayerVitalOptions.Defaults(false),false,.8);File.WriteAllText(Path.Combine(root,"vital-layout.json"),new JavaScriptSerializer().Serialize(inspected.Captions.ConvertAll(c=>new{c.Text,c.Bounds,c.Size,c.Outline})));
        Directory.CreateDirectory(Path.Combine(root,"designs"));VerifySignal();VerifyNarrow(root);var json=new JavaScriptSerializer();var legacy=new Dictionary<string,object>();var hp=PlayerVitalOptions.Read(legacy,false);var mp=PlayerVitalOptions.Read(legacy,true);Check(!hp.Bar.Enabled&&!mp.Bar.Enabled&&hp.Bar.MediumColor!=mp.Bar.MediumColor,"New visual modules are independent opt-ins");
        hp.Current.FontSize=32;hp.Current.Outline.Width=3;hp.Maximum.OffsetY=12;hp.Bar.ScalePercent=155;hp.DisplayScale=.75;hp.Opacity=70;hp.Bar.AutoHide=true;var copy=hp.Copy();copy.Current.Outline.Width=6;copy.Maximum.OffsetY=44;Check(hp.Current.Outline.Width==3&&hp.Maximum.OffsetY==12,"Deep snapshots preserve independent caption outlines/offsets");var restored=PlayerVitalOptions.Read(json.Deserialize<Dictionary<string,object>>(json.Serialize(new{playerHealth=hp})),false);Check(PlayerVitalOptions.Same(hp,restored),"Full appearance/behavior configuration persists");
        var bad=PlayerVitalOptions.Defaults(false);bad.Current=null;bad.Bar=null;bad.DisplayScale=double.NaN;bad.Bounds=new Rectangle(0,0,0,0);bad.Normalize();Check(bad.Current!=null&&bad.Bar!=null&&bad.DisplayScale==1&&bad.Bounds.Width==80,"Malformed configuration has safe defaults");
        foreach(bool mana in new[]{false,true}){
            var exact=PlayerVitalDesign.Measure(PlayerVitalOptions.Defaults(mana),mana,.5,10123,12683);Check(exact.Captions[1].Text=="10 123"&&exact.Captions[2].Text=="/ 12 683"&&exact.Captions[3].Text=="80%","Live labels use actual values while fill animation is in progress");
            var o=PlayerVitalOptions.Defaults(mana);var basis=PlayerVitalDesign.Measure(o,mana,.8);Check(basis.Captions.Count==4&&basis.Captions[2].Bounds.Left>basis.Captions[1].Bounds.Right,"Maximum follows current without overlap");Check(basis.Captions[2].Size<basis.Captions[1].Size,"Approved hierarchy keeps maximum smaller");
            var original=o.Copy();o.Bar.ScalePercent=150;var scaled=PlayerVitalDesign.Measure(o,mana,.8);Check(o.EffectiveBounds.Width==original.Bounds.Width*1.5&&scaled.Captions[1].Size==36&&o.Current.FontSize==24,"Whole scale includes final-size glyphs without changing individual preferences");Check(o.EffectiveBounds.X+o.EffectiveBounds.Width/2==o.Bounds.X+o.Bounds.Width/2,"Scale retains anchor");
            o.Bar.ScalePercent=100;o.Current.FontSize=30;Check(PlayerVitalDesign.Measure(o,mana,.8).Captions[2].Size==16,"Independent maximum font");o.MaximumBesideCurrent=false;o.Maximum.Position=0;o.Maximum.OffsetY=-60;var moved=PlayerVitalDesign.Measure(o,mana,.8);Check(moved.Captions[2].Bounds.Y<0&&moved.Surface.Contains(moved.Captions[2].Bounds),"Free positions and offsets expand surface instead of clipping");
            var hiddenCurrent=original.Copy();hiddenCurrent.Current.Enabled=false;var without=PlayerVitalDesign.Measure(hiddenCurrent,mana,.8);Check(without.Captions[1].Bounds.Left>without.Captions[0].Bounds.Right,"Hiding current cannot overlap the label and paired maximum");var thin=original.Copy();thin.Bounds=new Rectangle(0,0,80,6);thin.BorderWidth=4;thin.DisplayScale=4;using(var surface=PlayerVitalDesign.Render(thin,mana,.01,false))Check(surface.Bitmap.Width>0,"Thick frame at minimum thickness remains renderable");
            foreach(int percent in new[]{0,25,72,80,100})using(var surface=PlayerVitalDesign.Render(original,mana,percent/100.0,false)){Check(surface.Bitmap.GetPixel(0,0).A==0,"Transparent canvas has no opaque panel");surface.Bitmap.Save(Path.Combine(root,"designs","player-"+(mana?"mp":"health")+"-"+percent+".png"));}
            using(var process=Process.GetCurrentProcess()){uint before=OverlayNative.GetGuiResources(process.Handle,0);for(int i=0;i<64;i++)using(var surface=PlayerVitalDesign.Render(original,mana,(i%101)/100.0,true)){}uint after=OverlayNative.GetGuiResources(process.Handle,0);Check(after<=before+3,"Repeated vital rendering releases GDI resources");}
        }
        var large=new[]{new WidgetDisplayLayout.Area{Name="A",Bounds=new Rectangle(0,0,2560,1440),Working=new Rectangle(0,0,2560,1400),Primary=true}};var small=new[]{new WidgetDisplayLayout.Area{Name="A",Bounds=new Rectangle(0,0,1920,1080),Working=new Rectangle(0,0,1920,1040),Primary=true}};var config=new EnergyConfiguration{Options=new EnergyBarOptions(),Bounds=new Rectangle(200,200,400,6)};config.PlayerHealth.Bar.Enabled=true;var display=new WidgetDisplayLayout();display.Capture(config,large);var projected=display.Adapt(config,small);Check(projected.PlayerHealth.Bounds.Width==315&&projected.PlayerHealth.DisplayScale==.75,"Display adaptation scales geometry and text layout");Check(PlayerVitalOptions.Same(config.PlayerHealth,display.Adapt(projected,large).PlayerHealth),"Reference restores full precision after monitor round trip");
        using(var owner=new EnergyOverlay(root,true)){
            var original=owner.Configuration;var c=original.Copy();c.PlayerHealth.Bar.Enabled=true;c.PlayerHealth.Bar.ScalePercent=175;c.PlayerMana.Percentage.OffsetY=25;owner.ApplyConfiguration(c);var actual=owner.Configuration;Check(actual.PlayerHealth.Bar.ScalePercent==175&&actual.PlayerMana.Percentage.OffsetY==25&&actual.Bounds==original.Bounds&&DpsOptions.Same(actual.Dps,original.Dps),"Applying player visuals preserves other widgets");owner.UndoConfiguration();Check(ConfigurationHistory.Same(owner.Configuration,original),"Player visual changes participate in shared undo");
            using(var health=new PlayerVitalOverlay(owner,false,true))health.VerifySafety();using(var mana=new PlayerVitalOverlay(owner,true,true))mana.VerifySafety();var settings=new HelperSettings(owner);try{settings.VerifyPlayerVitals(root);}finally{settings.Close();}
        }
        File.WriteAllText(Path.Combine(root,"player-vitals-test.txt"),"PASS: actual own HP/MP profiles and deltas; actor/flow isolation; explicit maximum down/up; zero resources; stale/zone/transport reset; no estimates; atomic malformed-frame rejection and parser fuzz; narrow labels/outlines, bitmap DPI and preview sliders; styles/fonts/offsets/outlines; scale/display round trip; persistence/undo/isolation; bounded GDI; no additional polling timer; no-data editing samples hidden when locked; static images cached; EN/ES settings.");
    }
    internal static void Replay(string root,string frames){
        var s=new PlayerVitalSignal();s.Configure(true);var json=new JavaScriptSerializer();bool initial=false,mp4304=false,hp10195=false,hp10123=false,lower=false,restored=false;int own=0,changes=0;var events=new List<object>();
        foreach(var line in File.ReadLines(frames)){var row=json.Deserialize<Dictionary<string,object>>(line);string hex=(string)row["hex"];var b=new byte[hex.Length/2];for(int i=0;i<b.Length;i++)b[i]=Convert.ToByte(hex.Substring(i*2,2),16);double t=Convert.ToDouble(row["ts"]);s.Consume(b,0,b.Length,t,(string)row["stream"]);var hp=s.Read(false,t);var mp=s.Read(true,t);if(hp==null||mp==null)continue;if(hp.Actor!=13351)continue;if(row["opcode"].ToString()=="3336"){own++;initial|=hp.Current==12683&&hp.Maximum==12683&&mp.Current==4625&&mp.Maximum==4625;}mp4304|=mp.Current==4304;hp10195|=hp.Current==10195;hp10123|=hp.Current==10123;if(hp.Maximum==12387)lower=true;if(lower&&hp.Maximum==12683)restored=true;if(row["opcode"].ToString()=="008D"){changes++;events.Add(new{ts=t,hp=hp.Current,hpMaximum=hp.Maximum,mp=mp.Current,mpMaximum=mp.Maximum});}}
        Check(initial&&mp4304&&hp10195&&hp10123&&lower&&restored,"Actual capture must reproduce every user-confirmed HP/MP baseline, poison, MP consumption and equipment maximum transition");File.WriteAllText(Path.Combine(root,"player-vitals-replay-evidence.json"),json.Serialize(new{ownProfiles=own,events=events}));File.WriteAllText(Path.Combine(root,"player-vitals-replay-test.txt"),"PASS: actual user-confirmed own profile12683/12683 HP,4625/4625 MP; MP4304; poison HP10195 and10123; equipment maximum12387 then12683; production resource reader replay, own profiles="+own+", resource observations="+changes+".");
    }
}
